  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
    utf8proc_ssize_t rpos;
    utf8proc_ssize_t wpos = 0;
    utf8proc_int32_t uc;
    for (rpos = 0; rpos < length; rpos++) {

if (options & UTF8PROC_COMPOSE) {
  utf8proc_int32_t *starter = NULL;
  const utf8proc_property_t *starter_property = NULL;
  utf8proc_propval_t max_combining_class = -1;
  utf8proc_ssize_t rpos;
  utf8proc_ssize_t wpos = 0;
  for (rpos = 0; rpos < length; rpos++) {
    utf8proc_int32_t current_char = buffer[rpos];
    if (current_char < 0 || current_char >= 0x110000) {
      /* grapheme-break sentinel or out-of-range codepoint: pass it through
         unchanged, but never compose across it, since we cannot inspect it
         (unsafe_get_property would OOB on utf8proc_stage1table, idx = uc >> 8).
         utf8proc_reencode drops what cannot be encoded, so this is invisible
         to utf8proc_map. */
      buffer[wpos++] = current_char;
      starter = NULL;
      starter_property = NULL;
      max_combining_class = -1;
      continue;

/* baseline: composition still happens */
{
    utf8proc_int32_t input[] = {0x0041, 0x0301};        /* "A" + combining acute */
    utf8proc_int32_t expected[] = {0x00c1};             /* "\u00c1" */
    check_normalize_utf32("compose", input, 2, expected, 1);
}

/* an out-of-range codepoint is preserved, and blocks composition across it
   (unsafe_get_property would read past utf8proc_stage1table) */
{
    utf8proc_int32_t input[] = {0x0041, 0x110000, 0x0301};
    check_normalize_utf32("out-of-range codepoint", input, 3, input, 3);
}

/* likewise the grapheme-break sentinel written by utf8proc_decompose_char */
{
    utf8proc_int32_t input[] = {0x0041, -1, 0x0301};
    check_normalize_utf32("grapheme-break sentinel", input, 3, input, 3);

// Must be between 0xc2 and 0xf4 inclusive to be valid
if ((utf8proc_uint32_t)(uc - 0xc2) > (0xf4-0xc2)) return UTF8PROC_ERROR_INVALIDUTF8;
if (uc < 0xe0) {         // 2-byte sequence
   // Must have valid continuation character
   if (str >= end || !utf_cont(*str)) return UTF8PROC_ERROR_INVALIDUTF8;
   *dst = ((uc & 0x1f)<<6) | (*str & 0x3f);
   return 2;
}
if (uc < 0xf0) {        // 3-byte sequence
   if ((str + 1 >= end) || !utf_cont(*str) || !utf_cont(str[1]))
      return UTF8PROC_ERROR_INVALIDUTF8;
   // Check for surrogate chars
   if (uc == 0xed && *str > 0x9f)
       return UTF8PROC_ERROR_INVALIDUTF8;
   uc = ((uc & 0xf)<<12) | ((*str & 0x3f)<<6) | (str[1] & 0x3f);
   if (uc < 0x800)
       return UTF8PROC_ERROR_INVALIDUTF8;
   *dst = uc;
   return 3;
}
// 4-byte sequence
// Must have 3 valid continuation characters
if ((str + 2 >= end) || !utf_cont(*str) || !utf_cont(str[1]) || !utf_cont(str[2]))
   return UTF8PROC_ERROR_INVALIDUTF8;
// Make sure in correct range (0x10000 - 0x10ffff)
if (uc == 0xf0) {
  if (*str < 0x90) return UTF8PROC_ERROR_INVALIDUTF8;
} else if (uc == 0xf4) {
  if (*str > 0x8f) return UTF8PROC_ERROR_INVALIDUTF8;
}
*dst = ((uc & 7)<<18) | ((*str & 0x3f)<<12) | ((str[1] & 0x3f)<<6) | (str[2] & 0x3f);

